# Figure 4 step 3: downstream analyses of the FROZEN score in TCGA-PAAD (ductal, n=146): clinical association, multivariable Cox, DEG/Reactome ORA, immune-evasion proxies.
suppressPackageStartupMessages({library(data.table); library(readxl); library(survival); library(limma); library(clusterProfiler); library(msigdbr); library(CoxBoost)})
root <- "${PROJECT_ROOT}"; res <- file.path(root, "04_results/2026-10-12_Figure4_GALNT_run01"); set.seed(666)
tr <- fread(file.path(res, "training_scores.csv")); E <- readRDS(file.path(res, "tcga_paad_ductal_expr_allgenes.rds")); E <- E[, tr$sample]; tr$patient <- substr(tr$sample, 1, 12)
cdr <- as.data.frame(read_excel("${TCGA_CDR_ROOT}/01_raw/pancan_endpoints/TCGA-CDR-SupplementalTableS1.xlsx", sheet = 1, .name_repair = "minimal"))
m <- merge(as.data.frame(tr), cdr[, c("bcr_patient_barcode", "age_at_initial_pathologic_diagnosis", "gender", "ajcc_pathologic_tumor_stage", "histological_grade")], by.x = "patient", by.y = "bcr_patient_barcode", sort = FALSE); stopifnot(identical(m$sample, tr$sample))
m$age <- suppressWarnings(as.numeric(m$age_at_initial_pathologic_diagnosis)); m$ageg <- ifelse(m$age > 65, ">65", "<=65"); m$male <- as.numeric(m$gender == "MALE")
m$stage_n <- suppressWarnings(as.numeric(as.roman(sub("^Stage ([IV]+).*", "\\1", m$ajcc_pathologic_tumor_stage)))); m$stage_n[!grepl("^Stage [IV]+", m$ajcc_pathologic_tumor_stage)] <- NA; m$stageg <- ifelse(m$stage_n <= 2, "Stage I-II", ifelse(m$stage_n >= 3, "Stage III-IV", NA))
m$gradeg <- ifelse(m$histological_grade %in% c("G1", "G2"), "G1-2", ifelse(m$histological_grade %in% c("G3", "G4"), "G3-4", NA)); m$grade_n <- ifelse(m$gradeg == "G3-4", 1, ifelse(m$gradeg == "G1-2", 0, NA)); m$sexg <- m$gender
## clinical association (panels H-J)
assoc <- rbindlist(lapply(c("stageg", "gradeg", "ageg", "sexg"), function(v) { t <- table(m$group, m[[v]]); data.table(variable = v, level = colnames(t), High = t["High", ], Low = t["Low", ], chisq_p = suppressWarnings(chisq.test(t)$p.value), fisher_p = fisher.test(t)$p.value) })); fwrite(assoc, file.path(res, "H_clinical_association_TCGA.csv"))
## multivariable Cox (per SD of score)
m$risk_z <- as.numeric(scale(m$risk))
sg <- list(stromal = c("COL1A1", "COL1A2", "COL3A1", "DCN", "LUM", "FAP"), immune = c("PTPRC", "CD3E", "CD8A", "CD68", "CD4", "CD19"), acinar = c("PRSS1", "CPA1", "CELA3A", "CTRB1", "PNLIP", "CEL"))
Zs <- t(scale(t(E))); for (s in names(sg)) m[[s]] <- as.numeric(scale(colMeans(Zs[intersect(sg[[s]], rownames(Zs)), , drop = FALSE])))
cx <- function(vars, nm) { f <- coxph(as.formula(paste("Surv(time, event) ~", paste(vars, collapse = "+"))), m); s <- summary(f)$coefficients; ci <- summary(f)$conf.int; data.table(model = nm, term = rownames(s), HR = s[, 2], lo = ci[, 3], hi = ci[, 4], p = s[, 5], n = f$n) }
mv <- rbind(cx("risk_z", "Score only"), cx(c("risk_z", "age", "male", "stage_n"), "M1: + age, sex, stage"), cx(c("risk_z", "age", "male", "stage_n", "grade_n"), "M1g: + grade"), cx(c("risk_z", "age", "male", "stage_n", "stromal", "immune", "acinar"), "M2: + stroma, immune, acinar proxies"))
fwrite(mv, file.path(res, "I_multivariable_cox_TCGA.csv")); print(mv[term == "risk_z"])
## DEG (High vs Low) + Reactome ORA (panel K).  Score genes (GALNT14/16) are excluded from the DEG list to avoid circularity.
E2 <- E[rowMeans(E) > 1 & apply(E, 1, sd) > 0, ]; des <- model.matrix(~ factor(m$group, levels = c("Low", "High"))); fit <- eBayes(lmFit(E2, des)); tt <- topTable(fit, coef = 2, number = Inf, sort.by = "P"); tt$gene <- rownames(tt); tt <- tt[!tt$gene %in% c("GALNT14", "GALNT16"), ]; fwrite(tt, file.path(res, "K_limma_High_vs_Low.csv"))
up <- tt$gene[tt$adj.P.Val < 0.05 & tt$logFC >= 0.5]; dn <- tt$gene[tt$adj.P.Val < 0.05 & tt$logFC <= -0.5]; cat("DEG up:", length(up), "down:", length(dn), "of", nrow(tt), "\n")
rg <- unique(as.data.frame(msigdbr(species = "Homo sapiens", collection = "C2", subcollection = "CP:REACTOME"))[, c("gs_name", "gene_symbol")])
ora <- rbindlist(lapply(c(up = "up", down = "dn"), function(nm) { g <- get(nm); if (length(g) < 5) return(NULL); o <- as.data.frame(enricher(g, TERM2GENE = rg, universe = tt$gene, minGSSize = 10, maxGSSize = 500, pvalueCutoff = 1, qvalueCutoff = 1)); if (!nrow(o)) return(NULL); o$direction <- ifelse(nm == "up", "Up in High", "Up in Low"); o }), fill = TRUE); if (nrow(ora)) fwrite(ora, file.path(res, "K_reactome_ora.csv")); if (nrow(ora)) print(head(ora[order(ora$p.adjust), c("Description", "direction", "Count", "p.adjust")], 12))
## immune-evasion proxies (panels L-M).  TIDE itself is not run (needs web portal); a TIDE-ready, per-gene mean-centred matrix is exported for later use.
sig <- list(`CD8 T effector` = c("CD8A", "CD8B", "GZMA", "GZMB", "PRF1", "IFNG"), `IFN-gamma response` = c("IFNG", "STAT1", "CXCL9", "CXCL10", "IDO1", "HLA-DRA"), `Immune checkpoints` = c("CD274", "PDCD1", "CTLA4", "LAG3", "HAVCR2", "TIGIT"), `T-cell exclusion (CAF/TGF-b)` = c("COL1A1", "COL1A2", "FAP", "ACTA2", "TGFB1", "TGFB3"), `MDSC-like` = c("CD33", "ITGAM", "S100A8", "S100A9", "ARG1", "CD14", "CSF3R"), `Treg` = c("FOXP3", "IL2RA", "CTLA4", "IKZF2", "TNFRSF18"))
sc <- sapply(sig, function(g) colMeans(Zs[intersect(g, rownames(Zs)), , drop = FALSE])); sc <- data.frame(sc, check.names = FALSE); sc$sample <- tr$sample
imm <- rbindlist(lapply(names(sig), function(s) { x <- sc[[s]]; ct <- suppressWarnings(cor.test(m$risk, x, method = "spearman")); data.table(signature = s, n_genes = length(intersect(sig[[s]], rownames(Zs))), spearman_rho = unname(ct$estimate), spearman_p = ct$p.value, wilcox_p = wilcox.test(x ~ m$group)$p.value, median_High = median(x[m$group == "High"]), median_Low = median(x[m$group == "Low"])) })); imm$BH <- p.adjust(imm$spearman_p, "BH"); fwrite(imm, file.path(res, "L_immune_proxies.csv")); fwrite(cbind(m[, c("sample", "risk", "group")], sc[, names(sig)]), file.path(res, "L_immune_proxy_scores.csv")); print(imm)
tide <- E[, ] - rowMeans(E); fwrite(data.frame(Gene = rownames(tide), round(tide, 4), check.names = FALSE), file.path(res, "L_TIDE_input_TCGA_PAAD_meancentered.txt"), sep = "\t")
## sensitivity: use all 177 PAAD (not only ductal) -> apply frozen model (z-score within this set)
fz <- readRDS(file.path(res, "FROZEN_model.rds")); cdr2 <- cdr[cdr$type == "PAAD", ]; cdr2$time <- as.numeric(cdr2$OS.time) / 30.4375; cdr2$event <- as.numeric(cdr2$OS)
xena <- file.path(root, "01_raw/TCGA_EBpp_RNASeqV2.geneExp.xena.gz"); hdr <- names(fread(cmd = paste("gzip -dc", xena), nrows = 0)); smp <- hdr[-1]; si <- data.frame(sample = smp, patient = substr(smp, 1, 12), code = substr(smp, 14, 15)); si <- si[si$code == "01" & si$patient %in% cdr2$bcr_patient_barcode & !duplicated(si$patient), ]
Ea <- fread(cmd = paste("gzip -dc", xena), select = c(1, match(si$sample, hdr)), data.table = FALSE); Ea <- Ea[!duplicated(Ea[[1]]), ]; rownames(Ea) <- Ea[[1]]; Ea[[1]] <- NULL; alm <- c(GALNTL2 = "GALNT15", GALNTL1 = "GALNT16", WBSCR17 = "GALNT17", GALNTL4 = "GALNT18"); rownames(Ea)[rownames(Ea) %in% names(alm)] <- alm[rownames(Ea)[rownames(Ea) %in% names(alm)]]; Za <- scale(t(as.matrix(Ea)[fz$genes, ])); a <- merge(data.frame(sample = si$sample, patient = si$patient, risk = fz$model$pred(data.frame(Za, check.names = FALSE))), cdr2[, c("bcr_patient_barcode", "time", "event")], by.x = "patient", by.y = "bcr_patient_barcode"); a <- a[is.finite(a$time) & a$time > 0, ]; a$hi <- as.numeric(a$risk > median(a$risk))
sens <- data.table(set = "All TCGA-PAAD (incl. non-ductal)", n = nrow(a), events = sum(a$event), logrank_p = 1 - pchisq(survdiff(Surv(time, event) ~ hi, a)$chisq, 1), HR_high_vs_low = exp(coef(coxph(Surv(time, event) ~ hi, a))), HR_per_SD = exp(coef(coxph(Surv(time, event) ~ scale(risk), a)))); fwrite(sens, file.path(res, "sensitivity_all_PAAD.csv")); print(sens)
## multivariable in GSE62452 (stage, grade available)
sc2 <- fread(file.path(res, "validation_scores.csv")); g <- as.data.frame(sc2[cohort == "GSE62452"]); g$risk_z <- as.numeric(scale(g$risk)); g$stage_n <- ifelse(grepl("^I[AB]?$|^II", g$stage), ifelse(grepl("^IV", g$stage), 4, ifelse(grepl("^III", g$stage), 3, 2)), ifelse(grepl("^IV", g$stage), 4, ifelse(grepl("^III", g$stage), 3, NA))); g$stage_hi <- as.numeric(g$stage_n >= 3); g$grade_hi <- ifelse(g$grade %in% c("G3", "G4"), 1, ifelse(g$grade %in% c("G1", "G2"), 0, NA)); print(table(g$stage, useNA = "a")); print(table(g$grade, useNA = "a"))
f <- coxph(Surv(time, event) ~ risk_z + stage_hi + grade_hi, g); s <- summary(f); fwrite(data.table(model = "GSE62452: score + stage III-IV + grade 3", term = rownames(s$coefficients), HR = s$coefficients[, 2], lo = s$conf.int[, 3], hi = s$conf.int[, 4], p = s$coefficients[, 5], n = f$n), file.path(res, "I_multivariable_cox_GSE62452.csv")); print(s$coefficients)
fwrite(m[, c("sample", "patient", "risk", "group", "time", "event", "ageg", "sexg", "stageg", "gradeg")], file.path(res, "H_clinical_table_TCGA_samples.csv"))
